import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readPageFile(e){return readFileSync(resolve(__dirname,"../../frontend/padma-shri-explorer",e),"utf-8")}function readLandingFile(){return readFileSync(resolve(__dirname,"../../frontend/awards-of-india-explorer/index.html"),"utf-8")}describe("Padma Shri Explorer — Page Structure",()=>{let e;beforeAll(()=>{e=readPageFile("index.html")}),it("contains hero title and badge info",()=>{expect(e).toContain('class="ps-hero-title"'),expect(e).toContain("Padma Shri Explorer"),expect(e).toContain("Fourth-Highest Civilian Honour")}),it("contains all required content sections",()=>{["history","eligibility","medal-design","selection","fields","recipients","timeline","facts","gallery"].forEach(t=>{expect(e).toContain(`id="${t}"`),expect(e).toContain(`data-tab="${t}"`)})}),it("contains famous and unsung recipients",()=>{expect(e).toContain("Shah Rukh Khan"),expect(e).toContain("Milkha Singh"),expect(e).toContain("Sudha Murty"),expect(e).toContain("Saalumarada Thimmakka"),expect(e).toContain("Jadav Payeng")}),it("links shared stylesheet, page stylesheet, and script",()=>{expect(e).toContain('href="../../styles.css"'),expect(e).toContain('href="style.css"'),expect(e).toContain('src="script.js"')})}),describe("Padma Shri Explorer — Assets & Script",()=>{it("includes a non-empty stylesheet",()=>{const e=readPageFile("style.css");expect(e.length).toBeGreaterThan(1e3),expect(e).toContain(".ps-hero")}),it("includes valid interactive script",()=>{const e=readPageFile("script.js");expect(e).toContain("initTabs")})}),describe("Padma Shri Explorer — Landing Page Integration",()=>{it("is linked on the Awards of India Explorer Landing Page",()=>{const e=readLandingFile();expect(e).toContain("Padma Shri"),expect(e).toContain("../padma-shri-explorer/index.html")})});